function spec(l,i){const join=l.panel.startsWith('join-'),descent=l.panel.endsWith('-descent'),width=join?768:descent?1795:2048,height=join?720:descent?876:683,pad=8,minX=Math.min(...l.poly.map(p=>p[0])),minY=Math.min(...l.poly.map(p=>p[1])),maxX=Math.max(...l.poly.map(p=>p[0])),maxY=Math.max(...l.poly.map(p=>p[1]));return {...l,index:i,key:'city-ambient-'+i,join,refWidth:width,refHeight:height,x:Math.max(0,minX-pad),y:Math.max(0,minY-pad),w:Math.min(width,maxX+pad)-Math.max(0,minX-pad),h:Math.min(height,maxY+pad)-Math.max(0,minY-pad),frames:12,fps:l.kind==='fire'?14:l.kind==='light'?10:l.kind==='smoke'?2:l.kind==='cloth'?6:8};}
